def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    singleton = next((v for v, n in counts.items() if n == 1), None)
    if singleton is None:
        return out
    # A same-colored pair on an edge launches an inward ray in the column
    # under/above its first cell. The ray uses the singleton's color; when it
    # reaches that singleton, it changes it to 4 and stops.
    for r, dr in ((0, 1), (h - 1, -1)):
        for c in range(w - 1):
            pair = grid[r][c]
            if pair == grid[r][c + 1] and pair != bg and pair != singleton:
                rr = r + dr
                while 0 <= rr < h:
                    if grid[rr][c] == singleton:
                        out[rr][c] = 4
                        break
                    if grid[rr][c] == bg:
                        out[rr][c] = singleton
                    rr += dr
    return out

