def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Border runs define rectangular inward projections. Fill projected
    # interior spans with the sparse interior marker; markers become 4.
    marker = min((v for v in counts if v != bg), key=lambda v: counts[v])
    for edge in (0, h - 1):
        c = 0
        while c < w:
            if grid[edge][c] == bg:
                c += 1
                continue
            color = grid[edge][c]
            start = c
            while c < w and grid[edge][c] == color:
                c += 1
            for r in range(1, h - 1):
                for x in range(start, c):
                    out[r][x] = 4 if grid[r][x] == marker else marker
    return out

